UPDATE clunk_marketplace_listings SET title = '시장 노점', description = '진열대에 당근·양배추·토마토·감자 상자가 놓인 시장 노점입니다. 상자 자리는 저마다 이름 붙은 별도 부품이고 값을 적는 팻말까지 따로 있어 품목을 바꿔 끼울 수 있습니다.' WHERE slug = 'cozy-market-stall';
UPDATE clunk_marketplace_listings SET title = '코지 창고 헛간', description = '농기구와 수확물을 넣어 두는 나무 창고 헛간입니다. 문이 경첩 자리(door_pivot)에 별도 부품으로 달려 있어 그 부품만 돌리면 열리고 닫히며, 경첩 쇠붙이도 따로 들어 있습니다.' WHERE slug = 'cozy-storage-shed';
UPDATE clunk_marketplace_listings SET title = '울타리 문', description = '울타리에 다는 나무 문입니다. 문짝이 경첩 자리(gate_pivot)에 달려 있어 여닫는 연출을 바로 붙일 수 있고, 기둥 쪽 경첩 핀과 문짝 쪽 걸쇠가 따로 들어 있습니다.' WHERE slug = 'cozy-fence-gate';
UPDATE clunk_marketplace_listings SET title = '코지 팜 세트 Vol.1 (3종 묶음)', description = '시장 좌판과 창고 헛간, 울타리 문을 한 번에 받는 묶음입니다. 진열대의 상자 자리, 헛간 문, 울타리 문짝이 모두 이름 붙은 별도 부품이라 바꿔 끼우거나 여닫게 만들기 쉽습니다. 셋 다 같은 팔레트와 같은 축척으로 만들어 한 장면에 나란히 놓입니다.' WHERE slug = 'cozy-farm-set-vol1';
UPDATE clunk_marketplace_listings SET title = '나무 6종 팩', description = '잎이 넓은 나무 넷과 침엽수 둘, 여섯 그루가 들어 있는 나무 묶음입니다. 그루마다 줄기와 잎 두 덩이로 나뉘고 색이 모델에 들어 있어 텍스처 파일이 없으며, 멀리서 바꿔 끼울 단순 버전(LOD)은 아직 없습니다. 뿌리 쪽이 바닥보다 내려가 있으니 땅에 놓을 때 그만큼 올려 주세요.' WHERE slug = 'grove-tree-pack-vol1';
UPDATE clunk_marketplace_listings SET title = '소형 트랙터', description = '농장 게임이 실제로 굴리는 소형 트랙터입니다. 캐빈과 배기관, 전조등까지 들어 있고 앞뒤 차축과 조향 축, 뒤에 작업기를 거는 자리가 저마다 이름 붙은 별도 부품이라 바퀴를 굴리고 앞바퀴를 꺾을 수 있습니다. 색이 재질에 들어 있어 텍스처 파일 없이 바로 씁니다.' WHERE slug = 'hf-tractor-compact';
UPDATE clunk_marketplace_listings SET title = '경운기', description = '트랙터 뒤에 걸어 밭을 가는 경운 작업기입니다. 갈퀴와 깊이 조절대, 땅을 짚는 게이지 휠이 각각 이름 붙은 축으로 나뉘어 있어 흙에 박히는 동작을 붙일 수 있고, 트랙터에 거는 링크 자리에도 이름이 붙어 있습니다.' WHERE slug = 'hf-cultivator-compact';
UPDATE clunk_marketplace_listings SET title = '파종기', description = '씨앗 통을 얹고 줄뿌림하는 파종기입니다. 통마다 여닫는 뚜껑이 달려 있고 파종 유닛의 계량기와 게이지 휠, 복토 바퀴가 이름 붙은 축으로 나뉘어 있어 돌아가는 연출을 그대로 붙일 수 있습니다. 트랙터와 같은 손맛으로 만들어 나란히 두면 한 세트로 보입니다.' WHERE slug = 'hf-seeder-compact';
UPDATE clunk_marketplace_listings SET title = '가공 라인', description = '수확물을 넣어 가공품으로 만드는 실내 설비 한 줄입니다. 컨베이어와 호퍼, 제어반이 한 파일에 들어 있고 믹서 축과 펌프 축, 원료가 들어가고 나오는 자리가 이름 붙은 부품이라 작업 장면을 바로 채웁니다.' WHERE slug = 'hf-processing-line';
UPDATE clunk_marketplace_listings SET title = '농가', description = '농가 본채입니다. 나뭇결이 제각각인 지붕널과 굴뚝, 기둥을 세운 현관, 꽃을 심은 창문 화단, 집을 두른 돌 기초까지 게임에 서 있는 그대로 들어 있습니다. 색이 재질에 들어 있어 텍스처 파일 없이 바로 씁니다.' WHERE slug = 'hf-farmhouse';
UPDATE clunk_marketplace_listings SET title = '헛간', description = '앞이 트인 붉은 헛간과 곡물 사일로가 한 파일에 들어 있습니다. 널판을 덧댄 벽과 얼룩덜룩한 지붕널, 테를 두른 원통 사일로가 그대로이고 헛간 안쪽까지 뚫려 있어 트랙터를 세워 둘 수 있습니다.' WHERE slug = 'hf-barn';
UPDATE clunk_marketplace_listings SET title = '농부', description = '밀짚모자에 데님 작업복을 입은 농부입니다. 골반·척추·머리·팔다리가 이름 붙은 관절로 이어진 리그라 파일 안에 든 동작이 그대로 재생되고, 손에 도구를 붙이는 자리도 따로 있습니다. 대기·걷기·살펴보기·물주기·괭이질·수확 동작이 파일에 들어 있습니다.' WHERE slug = 'hf-player-farmhand';
UPDATE clunk_marketplace_listings SET title = '풍차', description = '돌을 쌓은 기단 위에 올라선 풍차입니다. 붉은 지붕과 살을 댄 날개, 작은 문과 창, 허리를 두른 난간이 들어 있고 날개 축이 이름 붙은 부품이라 파일 안의 회전 동작이 그대로 돌아갑니다. Apache-2.0 코드 각색본입니다.' WHERE slug = 'hf-windmill';
UPDATE clunk_marketplace_listings SET title = '빗물통', description = '빗물을 받아 두는 나무 물통입니다. 테를 두른 통 몸통에 물을 받는 꼭지와 뚜껑 손잡이가 달렸고, 쇠 다리로 띄워 세운 발치에 디딤돌이 놓여 있습니다.' WHERE slug = 'hf-water-butt';
UPDATE clunk_marketplace_listings SET title = '건초 롤 (온전한 것)', description = '끈으로 동여맨 원통형 건초 롤입니다. 건초 뭉치와 끈, 발치에 흩어진 짚이 각각 다른 부품이고 색이 모델에 들어 있어 텍스처 파일이 없습니다.' WHERE slug = 'cozy-haystack-full';
UPDATE clunk_marketplace_listings SET title = '건초 롤 (헐린 것)', description = '한쪽을 헐어 쓴 건초 롤입니다. 온전한 롤과 크기가 같아 나란히 두면 시간이 지난 자리로 읽히고, 색이 모델에 들어 있어 텍스처 파일이 없습니다.' WHERE slug = 'cozy-haystack-used';
